require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$id=(int)$_SESSION['id'];$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save'])){$about=substr(trim((string)($_POST['aboutcontent']??'')),0,32768);$s=tt_prepare($db,'UPDATE `accounts` SET `aboutcontent`=? WHERE `id`=?');$s->bind_param('si',$about,$id);if($s->execute()){$notice='Account description saved.';$_SESSION['aboutcontent']=$about;}else{$error=$s->error;}$s->close();}$s=tt_prepare($db,'SELECT `username`,`email`,`aboutcontent`,`hostmode`,`created_at`,`last_login_at`,`protected_account` FROM `accounts` WHERE `id`=? LIMIT 1');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();$db->close();if(!$row)tt_fail('Account record was not found.',404,'Account');
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Account</title></head><body><?php tt_nav('account.php');?><main class="content"><h2>Account</h2><?php if($notice):?><p class="notice ok"><?=tt_h($notice)?></p><?php endif;?><?php if($error):?><p class="notice error"><?=tt_h($error)?></p><?php endif;?><section class="card"><p><strong>Name:</strong> <?=tt_h($row['username'])?></p><p><strong>Email:</strong> <?=tt_h($row['email'])?></p><p><strong>Node role:</strong> <?=((int)$row['hostmode']>=2?'Admin/coordinator':((int)$row['hostmode']>=1?'Host':'Client'))?></p><p><strong>Created:</strong> <?=tt_h($row['created_at'])?></p><p><strong>Last login:</strong> <?=tt_h($row['last_login_at'])?></p><div class="actions"><a href="usrchange.php">Change credentials</a><a href="colorpick.php">Theme</a><a href="file.php">Files</a></div></section><form method="post"><h3>Profile description</h3><textarea name="aboutcontent" maxlength="32768"><?=tt_h($row['aboutcontent'])?></textarea><input type="submit" name="save" value="Save description"></form></main></body></html>